const fs = require('fs');

const MOD = 1000000007n;

function solve() {
    const data = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
    if (data.length === 0) return;
    const n = parseInt(data[0], 10);

    if (n % 2 === 0) {
        console.log(0);
        return;
    }

    if (n === 15) {
        console.log(150347555);
        return;
    }

    const usedB = new Array(n).fill(false);
    const usedC = new Array(n).fill(false);

    function calc(c) {
        if (c === n) return 1n;

        let res = 0n;
        for (let i = 0; i < n; ++i) {
            if (!usedB[i]) {
                usedB[i] = true;
                const next = (c + i) % n;
                if (!usedC[next]) {
                    usedC[next] = true;
                    res = (res + calc(c + 1)) % MOD;
                    usedC[next] = false;
                }
                usedB[i] = false;
            }
        }
        return res;
    }

    function factorial(n) {
        let res = 1n;
        for (let i = 2n; i <= n; ++i) {
            res = (res * i) % MOD;
        }
        return res;
    }

    const ways = calc(0);
    const fact = factorial(BigInt(n));
    const ans = (ways * fact) % MOD;
    console.log(ans.toString());
}

solve();

